const raw=$input.first().json||{}; let e=raw;
if(raw.content!==undefined){
  if(typeof raw.content==='string') e=JSON.parse(raw.content);
  else if(raw.content&&raw.content.type==='Buffer'&&Array.isArray(raw.content.data)) e=JSON.parse(Buffer.from(raw.content.data).toString('utf8'));
  else if(typeof raw.content==='object') e=raw.content;
}
const data=e.data||{}; const uuid=/^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
if(e.eventType!=='data.cleaning.requested') throw new Error('Unexpected eventType');
if(e.version!==1) throw new Error('Unsupported data-cleaning event version');
if(!uuid.test(String(e.eventId||''))||!uuid.test(String(data.workflowRunId||''))) throw new Error('eventId and workflowRunId must be UUIDs');
if(!['ALL','FILTER'].includes(data.scope)) throw new Error('scope must be ALL or FILTER');
return [{json:{eventId:e.eventId,eventType:e.eventType,version:e.version,workflowRunId:data.workflowRunId,scope:data.scope,filter:data.filter??null,triggeredByUserId:data.triggeredByUserId??null,timestamp:data.timestamp||e.occurredAt,receivedAt:new Date().toISOString()}}];

const response=$input.first().json||{}; const run=$node['Code: Validate Event'].json;
const list=response.leads||response.items||response.data?.leads||response.data?.items||response.data||[];
if(!Array.isArray(list)) throw new Error('Lead batch response must be an array');
const normalized=list.map(l=>({id:l.id,firstName:l.firstName??null,lastName:l.lastName??null,email:l.email??null,phone:l.phone??null,companyName:l.companyName??null,companyWebsite:l.companyWebsite??null,jobTitle:l.jobTitle??null,industry:l.industry??null,notes:l.notes??null}));
if(normalized.some(x=>!x.id)) throw new Error('Every lead batch row must include id');
return [{json:{...run,leads:normalized,totalLeadsScanned:normalized.length}}];

const input=$input.first().json; const findings=[]; const duplicateCandidates=[];
const makeId=()=>crypto.randomUUID();
const emailMap=new Map(), phoneMap=new Map();
for(const lead of input.leads){
  if(lead.email){const key=lead.email.trim().toLowerCase();if(!emailMap.has(key))emailMap.set(key,[]);emailMap.get(key).push(lead);}
  if(lead.phone){const key=lead.phone.replace(/[^0-9+]/g,'');if(key.length>=8){if(!phoneMap.has(key))phoneMap.set(key,[]);phoneMap.get(key).push(lead);}}
}
const add=(lead,fieldName,issueType,severity,currentValue,proposedValue,reason,safeToApply,confidence=1)=>findings.push({
  id:makeId(),recordType:'Lead',recordId:lead.id,
  leadIdentifier:`${lead.firstName||''} ${lead.lastName||''} (${lead.email||'No email'})`.trim(),
  fieldName,issueType,severity,currentValue,proposedValue,confidence,reason,safeToApply,
  requiresHumanApproval:true,source:'DETERMINISTIC'
});
for(const group of emailMap.values()) if(group.length>1){
  duplicateCandidates.push({candidateLeadIds:group.map(x=>x.id),matchField:'email',matchStrength:'EXACT'});
  for(const lead of group) add(lead,'email','DUPLICATE_CANDIDATE','CRITICAL',lead.email,
    `Duplicate conflict with ${group.length-1} other record(s)`,
    'Lead shares exact normalized email with another Lead. Manual review required.',false,0.99);
}
for(const group of phoneMap.values()) if(group.length>1){
  duplicateCandidates.push({candidateLeadIds:group.map(x=>x.id),matchField:'phone',matchStrength:'NORMALIZED'});
  for(const lead of group) add(lead,'phone','DUPLICATE_CANDIDATE','HIGH',lead.phone,
    `Duplicate phone conflict with ${group.length-1} other record(s)`,
    'Lead shares normalized phone with another Lead. Manual review required.',false,0.95);
}
const emailRegex=/^[^\s@]+@[^\s@]+\.[^\s@]+$/;
for(const lead of input.leads){
  if(!lead.firstName||!String(lead.firstName).trim()) add(lead,'firstName','MISSING_FIELD','HIGH',lead.firstName??null,null,'Required firstName is missing or blank.',false,1);
  for(const field of ['firstName','lastName','companyName','jobTitle','industry']){
    const value=lead[field]; if(typeof value==='string'&&value!==value.trim()) add(lead,field,'WHITESPACE_TRIM','LOW',value,value.trim(),'Leading/trailing whitespace detected by deterministic rule.',true,1);
  }
  if(typeof lead.email==='string'&&lead.email){
    const trimmed=lead.email.trim();const lower=trimmed.toLowerCase();
    if(lead.email!==trimmed) add(lead,'email','WHITESPACE_TRIM','LOW',lead.email,lower,'Email contains surrounding whitespace; proposed value is trimmed and lowercased.',true,1);
    else if(lead.email!==lower) add(lead,'email','CASE_NORMALIZATION','LOW',lead.email,lower,'Email contains uppercase characters; normalized to lowercase.',true,1);
    if(!emailRegex.test(lower)) add(lead,'email','INVALID_EMAIL','HIGH',lead.email,null,'Email does not match the basic address format; no replacement is guessed.',false,0.98);
  }
  if(typeof lead.companyWebsite==='string'&&lead.companyWebsite.trim()){
    const rawWeb=lead.companyWebsite.trim();
    if(!/^https?:\/\//i.test(rawWeb)) add(lead,'companyWebsite','INVALID_WEBSITE','LOW',lead.companyWebsite,
      'https://'+rawWeb.replace(/^www\./i,'').replace(/\/+$/,''),'Website has no protocol; proposed https URL needs confirmation.',true,0.95);
    else if(rawWeb.includes(',')) add(lead,'companyWebsite','INVALID_WEBSITE','MEDIUM',lead.companyWebsite,
      rawWeb.replace(/,/g,'.'),'Website domain contains comma; proposed dot substitution needs confirmation.',true,0.98);
  }
  if(typeof lead.phone==='string'&&lead.phone){
    const rawPhone=lead.phone.trim();const cleaned=rawPhone.replace(/[^0-9+]/g,'');
    if(rawPhone!==cleaned&&cleaned.length>=9) add(lead,'phone','INCONSISTENT_PHONE','LOW',lead.phone,cleaned,
      'Phone has formatting noise; normalized dialable characters only.',true,0.92);
  }
}
return [{json:{...input,deterministicFindings:findings,duplicateCandidates,deterministicIssueCount:findings.length}}];

const s=$input.first().json;
const duplicateLeadIds=[...new Set(s.duplicateCandidates.flatMap(x=>x.candidateLeadIds))];
const ambiguousCases=s.duplicateCandidates.map(x=>({type:'POTENTIAL_DUPLICATE',candidateLeadIds:x.candidateLeadIds,matchField:x.matchField,matchStrength:x.matchStrength}));
// Keep only company/profile attributes; do not send personal names or contact details to Gemini.
const minimizedLeads=s.leads.filter(l=>duplicateLeadIds.includes(l.id)).slice(0,100).map(l=>({
  id:l.id,companyName:l.companyName,companyWebsite:l.companyWebsite,
  jobTitle:l.jobTitle,industry:l.industry
}));
const prompt=`You are a CRM data-quality suggestion assistant. Return JSON only: {"suggestions":[{"recordId":"UUID","fieldName":"field","proposedValue":null,"confidence":0.0,"reason":"evidence-based reason"}]}. Only suggest fields from companyName,companyWebsite,jobTitle,industry. Never suggest email, phone or personal names. Do not invent facts, merge records, or choose duplicate survivors. Duplicate detection has already been performed deterministically; only suggest corrections supported by the minimized company records. If no evidence supports a correction, return an empty suggestions array.
AMBIGUOUS_CASES=${JSON.stringify(ambiguousCases)}
MINIMIZED_RECORDS=${JSON.stringify(minimizedLeads)}`;
return [{json:{...s,ambiguousCases,minimizedLeads,prompt}}];

const ai=$input.first().json||{}; const ctx=$node['Code: Build Duplicate and AI Context'].json;
const rawText=ai.candidates?.[0]?.content?.parts?.map(p=>p.text||'').join('')||'';
let suggestions=[];
if(rawText){const clean=rawText.replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'').trim();const parsed=JSON.parse(clean);if(!Array.isArray(parsed.suggestions))throw new Error('Gemini suggestions must be an array');suggestions=parsed.suggestions;}
const allowed=new Set(['companyName','companyWebsite','jobTitle','industry']);
const sourceById=new Map(ctx.leads.map(l=>[l.id,l])); const aiFindings=[];
for(const suggestion of suggestions){
  const lead=sourceById.get(suggestion.recordId); if(!lead||!allowed.has(suggestion.fieldName)) continue;
  if(typeof suggestion.confidence!=='number'||suggestion.confidence<0.7||suggestion.confidence>1) continue;
  const currentValue=lead[suggestion.fieldName]??null;
  if(suggestion.proposedValue===undefined||suggestion.proposedValue===currentValue) continue;
  aiFindings.push({id:crypto.randomUUID(),recordType:'Lead',recordId:lead.id,leadIdentifier:lead.email||lead.id,
    fieldName:suggestion.fieldName,issueType:'INCONSISTENT_DATA',severity:'MEDIUM',currentValue,
    proposedValue:suggestion.proposedValue,confidence:suggestion.confidence,
    reason:String(suggestion.reason||'AI suggestion requires human validation'),
    safeToApply:false,requiresHumanApproval:true,source:'AI_SUGGESTION'});
}
const findings=[...ctx.deterministicFindings,...aiFindings];
const issuesByType={},issuesBySeverity={};
for(const f of findings){issuesByType[f.issueType]=(issuesByType[f.issueType]||0)+1;issuesBySeverity[f.severity]=(issuesBySeverity[f.severity]||0)+1;}
const summary={totalLeadsScanned:ctx.totalLeadsScanned,totalIssuesFound:findings.length,issuesByType,issuesBySeverity,
  duplicatesFound:findings.filter(f=>f.issueType==='DUPLICATE_CANDIDATE').length,
  safeToApplyCount:findings.filter(f=>f.safeToApply).length};
const manualReviewNeeded=findings.some(f=>f.requiresHumanApproval);
return [{json:{workflowRunId:ctx.workflowRunId,status:'SUCCESS',summary,findings,manualReviewNeeded,duplicateCandidates:ctx.duplicateCandidates}}];
